package com.leetcode.easy;

import org.junit.Test;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import java.util.stream.Stream;

import static org.assertj.core.api.Assertions.*;

public class FindTheDifferenceTest {

  private final FindTheDifference classUnderTest = new FindTheDifference();

  String longInputS = "";
  String longInputT = "";
  @Test
  public void successTest() {
    assertThat(classUnderTest.findTheDifference("abcd", "abcde")).isEqualTo('e');
    assertThat(classUnderTest.findTheDifference("", "y")).isEqualTo('y');
    assertThat(classUnderTest.findTheDifference("a", "aa")).isEqualTo('a');
    assertThat(classUnderTest.findTheDifference(longInputS,longInputT)).isEqualTo('t');
  }
}